import { IconButton } from "../IconButton";
import { BareInput, InputStyling } from "../Input";
import { StyleFn } from "..";

// FIXME do we reuse ds-iconbutton component instead of a specific icon button style ?

export const NumericInput: StyleFn = (theme, mode) => {
  const { color, font, opacity, size } = theme;

  const { root: bareInput } = BareInput(theme, mode);
  const {
    root: input,
    _focused,
    _info,
    _valid,
    _invalid,
    _small,
    _large,
    _xlarge,
  } = InputStyling(theme, mode);
  const {
    root: button,
    _ghost: buttonGhost,
    _small: smallButton,
    _large: largeButton,
    _xlarge: xLargeButton,
  } = IconButton(theme, mode);

  return {
    root: {
      ...input,
      display: "inline-flex",
      padding: 0,
      "&:focus-within": _focused,
    },
    _info,
    _valid: {
      ..._valid,
      "&:focus-within": {
        boxShadow: `0 0 0 3px ${color.border.feedback.success[mode]} !important`,
      },
    },
    _invalid: {
      ..._invalid,
      "&:focus-within": {
        boxShadow: `0 0 0 3px ${color.border.feedback.error[mode]} !important`,
      },
    },
    _disabled: {
      userSelect: "none",
      pointerEvents: "none",
      opacity: opacity.disabled,
    },
    _small: {
      ..._small,
      paddingTop: 0,
      paddingBottom: 0,
      "& $button": {
        ...smallButton,
        minHeight: `calc(2rem - 1px)`,
      },
    },
    _large: {
      ..._large,
      paddingTop: 0,
      paddingBottom: 0,
      "& $button": {
        ...largeButton,
        minHeight: `calc(2rem - 1px)`,
      },
     "& $input": {
        "&[type=number]": {
          fontSize: font.size.medium,
          margin: `0 ${size.spacing[16]}`,
        }
      },
    },
    _xlarge: {
      ..._xlarge,
      paddingTop: 0,
      paddingBottom: 0,
      "& $button": {
        ...xLargeButton,
        minHeight: `calc(2rem - 1px)`,
      },
      "& $input": {
        "&[type=number]": {
          fontSize: font.size.large,
          margin: `0 ${size.spacing[24]}`,
        }
      },
    },
    input: {
      ...bareInput,
      textAlign: "center",
      margin: `0 ${size.spacing[12]}`,
      fontSize: font.size.small,
      // type="number" resets
      // see https://www.w3schools.com/howto/howto_css_hide_arrow_number.asp
      // Chrome, Safari, Edge, Opera
      "&::-webkit-inner-spin-button, &::-webkit-outer-spin-button": {
        ["-webkit-appearance"]: "none",
        margin: 0,
      },
      "&[type=number]": {
        padding: 0,
        // Firefox
        ["-moz-appearance"]: "textfield",
      },
    },
    button: {
      ...button,
      ...buttonGhost,
      color: color.text.accent.corporate[mode],
      cursor: "pointer",
      backgroundColor: color.surface.componentonbackground.moderate[mode],
      minHeight: `calc(2.5rem - 1px)`,
      marginBottom: 1,
      borderRadius: 0,
      "&:first-child": { borderTopLeftRadius: 3 },
      "&:last-child": { borderTopRightRadius: 3 },
      // FIXME hover/active color not designed in UIKit
      "&:hover": { backgroundColor: color.surface.componentonbackground.strong[mode] },
      "&:active": { backgroundColor: color.surface.componentonbackground.moderate[mode] },
    },
  };
};
